func invalidConfirmIntentPayloadFieldTypeError(err error) error {
	var typeErr *json.UnmarshalTypeError
	if !errors.As(err, &typeErr) {
		return err
	}
	field := typeErr.Field
	field = strings.TrimPrefix(field, "ConfirmIntentPayloadTransport.")
	if field == "" {
		field = "$payload"
	}
	metadata, ok := tools.LookupFieldMetadata(confirmIntentPayloadFields, field)
	if !ok || metadata.JSONType == "" {
		return err
	}
	actual := generatedUnmarshalJSONType(typeErr.Value)
	if actual == "" {
		return err
	}
	return tools.NewValidationError(
		err.Error(),
		[]*tools.FieldIssue{
			{
				Field:            field,
				Constraint:       "invalid_field_type",
				ExpectedJSONType: metadata.JSONType,
				ActualJSONType:   actual,
			},
		},
		nil,
	)
}
